const TabsList = defineUi<UI.ComponentProps<typeof TabsPrimitive.List> & VariantProps<typeof tabsListVariants>>("TabsList", ["class", "variant"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
