  const props = computed(() => omitProps(_props, ["class", "variant"]));
  const ctx = useContext(TabsContext);
  const value = computed(() => ({
    ...ctx.value,
    variant: variant.value ?? "default"
  }));
  return () => {
    return <TabsContext.Provider value={value.value}>
